{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'normal' AS period, round(avg(value)/1e6,1) AS avg_mb, round(max(value)/1e6,1) AS max_mb, count(*) AS n FROM normal_metrics WHERE service_name='reservation' AND metric='container.memory.usage' UNION ALL SELECT 'abnormal', round(avg(value)/1e6,1), round(max(value)/1e6,1), count(*) FROM abnormal_metrics WHERE service_name='reservation' AND metric='container.memory.usage'",
          "claim": "Reservation pod container memory averaged about 26 MB in the normal period and about 650 MB in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, metric, round(value/1e6,1) AS mb FROM abnormal_metrics WHERE service_name='reservation' AND metric IN ('container.memory.usage','k8s.pod.memory.working_set') AND time BETWEEN TIMESTAMP '2026-05-01 19:48:20+00' AND TIMESTAMP '2026-05-01 19:48:35+00' ORDER BY time, metric",
          "claim": "Reservation memory steps from about 27 MB to about 674 MB at 19:48:29 and stays there, with no restart or uptime reset."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS n, round(min(value),0) AS min_v, round(max(value),0) AS max_v FROM abnormal_metrics_sum WHERE service_name='reservation' AND metric='k8s.pod.uptime' GROUP BY 1,2",
          "claim": "Reservation pod uptime is continuous across the abnormal window (no restart), so the memory rise is not a crash-and-restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,2) AS p50_ms, round(quantile_cont(duration,0.9)/1e6,2) AS p90_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' AND attr_span_kind='Client') OR (service_name='reservation' AND span_name='reservation.Reservation/CheckAvailability' AND attr_span_kind='Server') GROUP BY 1,2,3",
          "claim": "Frontend's reservation CheckAvailability client calls wrap reservation's server spans, which sit on the user-facing /hotels path."
        }
      ]
    }
  ]
}
